<template>
  <section class="page-shell">
    <header class="page-header"><div><h1>投注热力</h1><p>今日未截止方案 · 同一玩法内独立投注项占比</p></div><button class="primary-button" type="button" @click="load">刷新</button></header>
    <section class="play-tabs app-card"><button v-for="play in plays" :key="play" type="button" :class="{active:playType===play}" @click="changePlay(play)">{{ play }}</button></section>
    <LoadingSkeleton v-if="loading" class="section-gap" type="cards" :count="4" />
    <ErrorState v-else-if="error" class="app-card section-gap" :description="error" @retry="load" />
    <template v-else>
      <section class="focus-card app-card section-gap"><header class="section-header"><div><span class="eyebrow">Center picks</span><h2>各玩法重心分析</h2><p>按真实投注数量提取</p></div></header><div v-if="focus.length" class="focus-grid"><article v-for="item in focus" :key="item.match_code+item.match_name"><span>{{ item.match_code || "--" }}</span><h3>{{ item.match_name || "--" }}</h3><strong>{{ item.option || "--" }}</strong><b>{{ number(item.count) }} 次</b><small>占比 {{ item.share ?? "--" }}%</small></article></div><EmptyState v-else title="暂无重心数据" description="当前玩法没有可提取的比赛" /></section>
      <section class="platform-card app-card section-gap"><header class="section-header"><div><h2>平台汇总</h2><p>赛事投注项次数</p></div></header><div v-if="platformSummary.length" class="platform-grid"><article v-for="item in platformSummary" :key="item.platform_id"><span>{{ item.platform_name || "--" }}</span><strong>{{ number(item.total_items) }}</strong><div><b v-for="option in (item.options||[]).slice(0,5)" :key="option.option">{{ option.option }} {{ number(option.count) }}</b></div></article></div><EmptyState v-else title="暂无平台汇总" description="接口未返回当前玩法的平台统计" /></section>
      <section class="matrix-card app-card section-gap"><header class="section-header"><div><h2>赛事投注冷热矩阵</h2><p>{{ playType }} · {{ (data.matches||[]).length }} 场</p></div><div class="legend"><span>低</span><i></i><i></i><i></i><i></i><span>高</span></div></header><div v-if="(data.matches||[]).length" class="matrix-list"><article v-for="match in data.matches" :key="match.match_code+match.match_name"><div class="matrix-match"><span>{{ match.match_code || "--" }}</span><h3>{{ match.home || "--" }} <i>VS</i> {{ match.away || "--" }}</h3><small>{{ match.league || "--" }} · {{ number(match.total_items) }} 个投注项</small></div><div class="matrix-options"><div v-for="option in match.options||[]" :key="option.option" :style="heatStyle(option.share)"><span>{{ option.option || "--" }}</span><strong>{{ option.share ?? "--" }}%</strong><small>{{ number(option.count) }} 次</small></div></div></article></div><EmptyState v-else title="暂无热力数据" description="今日未截止订单暂无该玩法数据" /></section>
    </template>
  </section>
</template>
<script setup>
import { computed,onMounted,ref } from "vue";import axios from "axios";import LoadingSkeleton from "../components/ui/LoadingSkeleton.vue";import EmptyState from "../components/ui/EmptyState.vue";import ErrorState from "../components/ui/ErrorState.vue"
const plays=["胜平负","让球胜平负","半全场","比分"],playType=ref("胜平负"),data=ref({}),loading=ref(true),error=ref("");const focus=computed(()=>data.value.focus||[]),platformSummary=computed(()=>data.value.platform_summary||[])
async function load(){loading.value=true;error.value="";try{const r=await axios.get("/api/portal/heatmap",{params:{play_type:playType.value}});if(!r.data||r.data.code!==200)throw new Error();data.value=r.data.data||{}}catch{data.value={};error.value="热力数据暂时无法读取，请稍后重试或检查接口连接状态"}finally{loading.value=false}}
function changePlay(v){playType.value=v;load()} function number(v){return Math.round(Number(v||0)).toLocaleString("zh-CN")} function heatStyle(v){const n=Number(v||0);return{background:n>=75?"#bcd71e":n>=50?"#d9ff35":n>=25?"#ebf5a6":n>0?"#f5f8dc":"#fafaf8"}} onMounted(load)
</script>
