:700}.matrix-match h3{margin:6px 0 4px;font-size:13px}.matrix-match h3 i{margin:0 4px;color:var(--text-muted);font-size:9px;font-style:normal}.matrix-match small{color:var(--text-muted);font-size:10px}.matrix-options{display:grid;grid-template-columns:repeat(auto-fit,minmax(95px,1fr));gap:6px}.matrix-options>div{min-height:72px;padding:10px;border-radius:10px;color:var(--text-main)}.matrix-options span,.matrix-options strong,.matrix-options small{display:block}.matrix-options span{font-size:10px}.matrix-options strong{margin-top:3px;font-size:18px}.matrix-options small{margin-top:2px;font-size:9px;opacity:.68}@media(max-width:900px){.focus-grid{grid-template-columns:repeat(2,1fr)}.matrix-list>article{grid-template-columns:1fr}}@media(max-width:520px){.play-tabs{width:100%;overflow-x:auto}.play-tabs button{white-space:nowrap}.focus-grid{grid-template-columns:1fr}}
